INSERT INTO warscape_enemy_family VALUES (9,'birds','Birds','Native kaliri/owl for jungle birds and ducks; carrion bird for seagulls/vultures; stock chicken.');
INSERT INTO warscape_enemy_family VALUES (10,'crabs','Crabs','Darkshore crawler displays 641/1000/1001, active melee forms only.');
INSERT INTO warscape_enemy_family VALUES (11,'crocodiles','Crocodiles','Classic Dreadmaw crocolisk display 1250; land form.');
INSERT INTO warscape_enemy_family VALUES (12,'dogs','Dogs','Scarlet Tracking Hound hyena display 2709; neutral wild dogs and hostile guards/jackals.');
INSERT INTO warscape_enemy_family VALUES (13,'monkeys','Monkeys','Scaled-down Stranglethorn gorilla displays 843/837 as approved ape stand-in.');
INSERT INTO warscape_enemy_family VALUES (14,'snakes','Snakes','Stock Adder 1986 for non-poisonous small snakes.');
INSERT INTO warscape_enemy_family VALUES (15,'terrorbirds','Terrorbirds','Unsaddled Mulgore plainstrider displays 1219/1221/178.');
